{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("case must contain nodes and required_symbols")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise ValueError("nodes must be an array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    required = set(required_symbols)
    by_id = {}
    roots = []
    fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in fields):
            raise ValueError("each node must contain all required fields")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a nonempty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("node symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("node depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("node utility must be numeric")

        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("nodes must contain exactly one root")

    root_id = roots[0]
    children = {node_id: set() for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            if node["depth"] != 0:
                raise ValueError("root depth must be zero")
            continue
        if parent not in by_id:
            raise ValueError("every parent must identify a node")
        if by_id[parent]["depth"] + 1 != node["depth"]:
            raise ValueError("node depths must match parent relationships")
        children[parent].add(node_id)

    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError("nodes must form a tree")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(by_id):
        raise ValueError("all nodes must belong to the rooted tree")

    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
        raise ValueError("all required symbols must be represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        symbol_counts[symbol] -= 1
        if all(symbol_counts.get(required_symbol, 0) > 0 for required_symbol in required):
            retained.remove(node_id)
            removed.append(node_id)
        else:
            symbol_counts[symbol] += 1

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
